\begin{ex}%[9H5N4-6]
\immini[thm]{
Cho $\Delta{PQR}$ vuông tại ${P}$, đường cao ${PT}$. Chọn khẳng định đúng? 

\choice
{  ${PQ}$ là tiếp tuyến của đường tròn $(P,PR)$ }
   {   ${PQ}$ là tiếp tuyến của đường tròn đường kính ${QR}$  }
     {   ${QR}$ là tiếp tuyến của đường tròn tâm ${T}$  }
    { \True  ${QR}$ là tiếp tuyến của đường tròn $(P,PT)$ }
}{
\begin{tikzpicture}[scale=0.6]  % Thu nhỏ toàn bộ hình vẽ
            % Tạo các điểm A, B, C, H
            \coordinate [label=above:{$P$}] (A) at (0, 4);
            \coordinate [label=below left:{$Q$}] (B) at (-3, 0);
            \coordinate [label=below right:{$R$}] (C) at (4, 0);
            \coordinate [label=below:{$T$}] (H) at (0, 0);

            % Vẽ các cạnh tam giác
            \draw (B) -- (A) -- (C) -- cycle;

            % Vẽ đường cao từ A xuống H
            \draw  (A) -- (H);

            % Vẽ góc vuông tại H
            \draw (H) rectangle ++(0.3, 0.3);   

            %Vẽ góc vuông tại A
            \pic[draw,angle radius=10]{right angle=B--A--C};
        \end{tikzpicture}
